120	  // a clock before any real run, so a route that reads new Date() fails here
121	  const demo = createApp({ pool, clock: { now: () => new Date('2026-10-14T13:30:00Z'), demo: true }, mailer, appUrl: '' });
122	  const slots = (await request(demo).get('/api/slots')).body;
123	  expect([slots.now, slots.demo, slots.slots[0].startsAt])
124	    .toEqual(['2026-10-14T13:30:00.000Z', true, '2026-10-14T16:00:00.000Z']); // 15:00Z is under 2 hours away
125	  expect((await request(demo).post('/api/bookings').send({ ...valid, startsAt: '2026-10-15T15:00:00Z' })).status).toBe(201);
126	  const mentors = (await request(demo).get('/api/mentors')).body;
127	  expect(mentors.demo).toBe(true);
128	  expect(mentors.mentors.flatMap((m: MentorDto) => m.bookings.map((b) => b.startsAt))).toContain('2026-10-15T15:00:00.000Z');
129	});
